#pragma once

#include <stdint.h>

// Bitmap fonts for the T-Dongle-S3 display, generated by
// scripts/gen-lcd-font.py into lcd_font.c (X11 misc-fixed, public domain).
//
// Character-cell fonts: every glyph is w x h pixels and advances by w.
// Glyph i (see dm_glyph_index() in display_model.h for the code point →
// index mapping) starts at bits[i * bytes_per_glyph]; its rows run top to
// bottom as one MSB-first bit stream, padded to whole bytes.

// Glyphs per font: printable ASCII (95) + Latin-1 supplement (96) + extras.
#define LCD_FONT_EXTRA_GLYPHS 9
#define LCD_FONT_GLYPHS       (95 + 96 + LCD_FONT_EXTRA_GLYPHS)

typedef struct {
    uint8_t        w;
    uint8_t        h;
    uint8_t        bytes_per_glyph;
    const uint8_t *bits;
} lcd_font_t;

// Code points of the glyphs after the Latin-1 block, in index order
// (index 191 + i). The first is U+2026, the ellipsis used for truncation.
extern const uint16_t lcd_font_extra_cps[LCD_FONT_EXTRA_GLYPHS];

extern const lcd_font_t lcd_font_large;   // 9x18 bold
extern const lcd_font_t lcd_font_small;   // 7x13 bold
